    // ===== AI 教学建议相关方法 =====

    // 根据表情分析结果触发AI建议
    async triggerAIAdvice(trigger, attentionScore, emotionCount) {
      const now = Date.now();
      // 每60秒最多触发一次，避免频繁调用
      if (now - this.lastAdviceTime < 60000) return;
      this.lastAdviceTime = now;
      this.adviceLoading = true;
      this.emotionTrigger = trigger;

      let prompt = '';
      if (attentionScore < 40) {
        this.adviceLevel = 'danger';
        this.adviceTag = '需要干预';
        this.triggerColor = '#F56C6C';
        prompt = `当前课堂分析显示学生专注度评分仅为${attentionScore}分（满分100），表情统计：专注${emotionCount['专注']||0}帧，开心${emotionCount['开心']||0}帧，惊讶${emotionCount['惊讶']||0}帧，愤怒${emotionCount['愤怒']||0}帧。请作为教学专家，给出3条简短具体的课堂干预建议，帮助提升学生注意力。每条建议不超过30字，直接列出，不要序号前缀。`;
      } else if (emotionCount['惊讶'] > emotionCount['专注'] * 0.3) {
        this.adviceLevel = 'warning';
        this.adviceTag = '学生困惑';
        this.triggerColor = '#E6A23C';
        prompt = `课堂分析显示学生惊讶表情占比较高（${emotionCount['惊讶']||0}帧），可能存在知识点理解困难。请给出3条简短的课堂互动建议，帮助教师了解学生困惑点。每条不超过30字，直接列出。`;
      } else if (attentionScore >= 70) {
        this.adviceLevel = 'success';
        this.adviceTag = '状态良好';
        this.triggerColor = '#67C23A';
        prompt = `课堂分析显示学生专注度${attentionScore}分，状态良好。请给出2条建议帮助教师保持并进一步提升课堂效果。每条不超过30字，直接列出。`;
      } else {
        this.adviceLevel = 'info';
        this.adviceTag = '一般';
        this.triggerColor = '#409EFF';
        prompt = `课堂专注度${attentionScore}分，处于中等水平。请给出2条提升课堂参与度的简短建议。每条不超过30字，直接列出。`;
      }

      try {
        const response = await fetch('https://api.deepseek.com/v1/chat/completions', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer sk-28688aee0c9b46e5b15c8ab9badfe924'
          },
          body: JSON.stringify({
            model: 'deepseek-chat',
            messages: [{ role: 'user', content: prompt }],
            max_tokens: 300,
            temperature: 0.7
          })
        });
        const data = await response.json();
        this.currentAdvice = data.choices?.[0]?.message?.content || '暂无建议';
      } catch (e) {
        this.currentAdvice = '获取AI建议失败，请检查网络连接。';
      } finally {
        this.adviceLoading = false;
      }
    },

    // 分析完成后调用（供外部或路由传参触发）
    async onAnalysisComplete(stats) {
      if (!stats) return;
      const score = stats.attention_score || 0;
      const ec = stats.emotion_count || {};
      let trigger = '';
      if (score < 40) trigger = '⚠️ 专注度过低';
      else if ((ec['惊讶']||0) > (ec['专注']||0) * 0.3) trigger = '❓ 学生存在困惑';
      else trigger = '✅ 分析完成';
      await this.triggerAIAdvice(trigger, score, ec);
    }
